16. 다음 파이썬 프로그램의 실행 결과는?
class Node:
def __init__(self, data, next):
self.data = data
self.next = next
class SinglyLinkedList:
def __init__(self):
self.head = None
def func1(self, data):
node = self.head
self.head = Node(data, node)
def func2(self, data):
if self.head is None: self.func1(data)
else :
node = self.head
while node.next is not None: node = node.next
node.next = Node(data, None)
def func3(self, pos):
if pos < 0: return None
node = self.head
while pos > 0 and node != None:
node = node.next
pos -= 1
return node
def showList(self):
node = self.head
while node :
print(node.data, end=' ')
node = node.next
myList = SinglyLinkedList()
myList.func1(1); myList.func2(2)
myList.func1(3); myList.func2(4)
myList.func2(myList.func3(0).data)
myList.showList()
①1 2 3 4
②2 3 4 1
③3 1 2 4 3
④3 3 1 2 4

17. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
#include <stdlib.h>
typedef struct ListNode {
int value;
struct ListNode* next;
} ListNode;
int func(ListNode* p, int n) {
int i, sum = 0;
for(i = 0; i < n; i++) {
sum += p->value;
p = p->next;
}
return sum;
}
int main() {
int i, s, SIZE = 5;
ListNode* p[SIZE];
for(i = 0; i < SIZE; i++) {
p[i] = (ListNode*)malloc(sizeof(ListNode));
p[i]->value = i;
}
for(i = 0; i < SIZE-1; i++)
p[i]->next = p[i+1];
p[SIZE-1]->next = p[0];
s = func(p[4], 7);
printf("%d", s);
return 0;
}
①14
②15
③16
④17

19. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
int func(int key, int low, int high, int* list) {
list[high+1] = key;
int i = 0;
for(i = low; list[i] != key; i++);
if(i == (high+1)) return -1;
return i;
}
int main(int argc, char* argv[]) {
int list[100] = {1, 2, 3, 4, 5, 6, 7};
printf("%d\n", func(3, 4, 6, list));
return 0;
}
